def install_policy():
    import uuid

    codes = [
        "packing.read",
        "packing.company",
        "packing.prepare",
        "packing.issue",
        "packing.download",
        "packing.void",
        "bom.read",
        "bom.create",
        "bom.edit",
        "bom.approve",
        "bom.archive",
        "material_plans.read",
        "material_plans.calculate",
        "material_plans.review",
    ]
    conn = op.get_bind()
    for code in codes:
        conn.execute(
            sa.text(
                "INSERT INTO permissions(id,code,description) VALUES (:id,:code,:code) ON CONFLICT(code) DO NOTHING"
            ),
            dict(id=uuid.uuid5(uuid.NAMESPACE_URL, "ambs:" + code), code=code),
        )
    policy = {
        "SUPER_ADMIN": codes,
        "OPERATIONS": [c for c in codes if c != "bom.approve"],
        "MANAGEMENT": [
            "packing.read",
            "packing.company",
            "packing.download",
            "bom.read",
            "bom.approve",
            "bom.archive",
            "material_plans.read",
            "material_plans.calculate",
            "material_plans.review",
        ],
        "PACKING": [
            "packing.read",
            "packing.company",
            "packing.prepare",
            "packing.download",
        ],
        "SALES": ["packing.read", "packing.company", "packing.download"],
        "DRIVER": ["packing.read", "packing.download"],
    }
    for role, grants in policy.items():
        for code in grants:
            conn.execute(
                sa.text(
                    "INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code=:role AND p.code=:code ON CONFLICT DO NOTHING"
                ),
                dict(role=role, code=code),
            )


def install_guards():
    for table in [
        "packing_documents",
        "packing_document_events",
        "material_plans",
        "material_plan_lines",
        "material_plan_reviews",
        "packing_planning_operations",
    ]:
        op.execute(
            f"CREATE TRIGGER {table}_history BEFORE UPDATE OR DELETE ON {table} FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_append_only()"
        )
    op.execute("""
    CREATE FUNCTION ambs_bom_version_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF TG_OP='DELETE' THEN RAISE EXCEPTION 'BOM history cannot be deleted' USING ERRCODE='23514'; END IF;
      IF TG_OP='INSERT' AND (NEW.status<>'DRAFT' OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL) THEN
        RAISE EXCEPTION 'A BOM must begin as an unapproved draft' USING ERRCODE='23514'; END IF;
      IF TG_OP='UPDATE' THEN
        IF (to_jsonb(OLD)-ARRAY['output_quantity','unit_id','effective_from','effective_until','source_reference','reason','version','status','approved_by','approved_at']) IS DISTINCT FROM
           (to_jsonb(NEW)-ARRAY['output_quantity','unit_id','effective_from','effective_until','source_reference','reason','version','status','approved_by','approved_at']) THEN
          RAISE EXCEPTION 'BOM identity is immutable' USING ERRCODE='23514'; END IF;
        IF OLD.status<>'DRAFT' AND (to_jsonb(OLD)-ARRAY['status','approved_by','approved_at']) IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['status','approved_by','approved_at']) THEN
          RAISE EXCEPTION 'Submitted BOM content is immutable' USING ERRCODE='23514'; END IF;
        IF NOT ((OLD.status='DRAFT' AND NEW.status IN ('DRAFT','PENDING_APPROVAL','ARCHIVED')) OR
          (OLD.status='PENDING_APPROVAL' AND NEW.status IN ('APPROVED','ARCHIVED')) OR
          (OLD.status='APPROVED' AND NEW.status IN ('SUPERSEDED','ARCHIVED')) OR
          (OLD.status='SUPERSEDED' AND NEW.status='ARCHIVED')) THEN
          RAISE EXCEPTION 'Invalid BOM transition' USING ERRCODE='23514'; END IF;
        IF OLD.status<>'PENDING_APPROVAL' OR NEW.status<>'APPROVED' THEN
          IF OLD.approved_by IS DISTINCT FROM NEW.approved_by OR OLD.approved_at IS DISTINCT FROM NEW.approved_at THEN
            RAISE EXCEPTION 'Approval evidence is immutable' USING ERRCODE='23514'; END IF;
        END IF;
      END IF;
      IF NEW.status IN ('DRAFT','PENDING_APPROVAL','APPROVED') AND NOT EXISTS(
        SELECT 1 FROM items i JOIN units u ON u.id=i.unit_id WHERE i.id=NEW.item_id AND i.unit_id=NEW.unit_id
          AND i.is_active AND u.is_active AND NEW.output_quantity=round(NEW.output_quantity,u.decimal_places)) THEN
        RAISE EXCEPTION 'BOM output requires the active item unit and valid precision' USING ERRCODE='23514'; END IF;
      IF NEW.previous_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bom_versions b WHERE b.id=NEW.previous_id AND b.item_id=NEW.item_id AND b.revision<NEW.revision) THEN
        RAISE EXCEPTION 'Invalid BOM revision lineage' USING ERRCODE='23514'; END IF;
      IF NEW.status IN ('PENDING_APPROVAL','APPROVED') AND (NOT EXISTS(SELECT 1 FROM bom_components WHERE bom_id=NEW.id) OR EXISTS(
        SELECT 1 FROM bom_components c JOIN items i ON i.id=c.item_id JOIN units u ON u.id=c.unit_id
        WHERE c.bom_id=NEW.id AND (i.unit_id<>c.unit_id OR NOT i.is_active OR NOT u.is_active OR c.quantity<>round(c.quantity,u.decimal_places)))) THEN
        RAISE EXCEPTION 'A submitted BOM requires valid components' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER bom_version_control BEFORE INSERT OR UPDATE OR DELETE ON bom_versions FOR EACH ROW EXECUTE FUNCTION ambs_bom_version_guard();
    CREATE FUNCTION ambs_bom_component_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE parent bom_versions; candidate bom_components;
    BEGIN
      IF TG_OP='DELETE' THEN candidate=OLD; ELSE candidate=NEW; END IF;
      SELECT * INTO parent FROM bom_versions WHERE id=candidate.bom_id FOR UPDATE;
      IF parent.status IS DISTINCT FROM 'DRAFT' OR (TG_OP='UPDATE' AND OLD.bom_id<>NEW.bom_id) THEN
        RAISE EXCEPTION 'Only draft BOM components may change' USING ERRCODE='23514'; END IF;
      IF TG_OP<>'DELETE' AND (parent.item_id=candidate.item_id OR NOT EXISTS(
        SELECT 1 FROM items i JOIN units u ON u.id=i.unit_id WHERE i.id=candidate.item_id AND i.unit_id=candidate.unit_id
        AND i.is_active AND u.is_active AND candidate.quantity=round(candidate.quantity,u.decimal_places))) THEN
        RAISE EXCEPTION 'Invalid BOM component or unit precision' USING ERRCODE='23514'; END IF;
      RETURN candidate;
    END $$;
    CREATE TRIGGER bom_component_control BEFORE INSERT OR UPDATE OR DELETE ON bom_components FOR EACH ROW EXECUTE FUNCTION ambs_bom_component_guard();
    CREATE FUNCTION ambs_packing_issue_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF NOT EXISTS(SELECT 1 FROM sales_deliveries WHERE id=NEW.delivery_id AND status='DISPATCHED') OR
         NEW.snapshot->>'delivery_id' IS DISTINCT FROM NEW.delivery_id::text OR
         NEW.snapshot->>'official' IS DISTINCT FROM 'true' OR
         NEW.snapshot->>'kind' IS DISTINCT FROM NEW.kind THEN
        RAISE EXCEPTION 'Official documents require actual dispatch evidence' USING ERRCODE='23514'; END IF;
      IF (NEW.revision=1 AND NEW.previous_id IS NOT NULL) OR (NEW.revision>1 AND NOT EXISTS(
        SELECT 1 FROM packing_documents p WHERE p.id=NEW.previous_id AND p.delivery_id=NEW.delivery_id AND p.kind=NEW.kind AND p.revision=NEW.revision-1)) THEN
        RAISE EXCEPTION 'Invalid document revision lineage' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER packing_issue_control BEFORE INSERT ON packing_documents FOR EACH ROW EXECUTE FUNCTION ambs_packing_issue_guard();
    """)
